            self.conn = sqlite3.connect(db_file)
            print(f"Successfully Connected to {db_file}")
        except Error as e:
            print(e)

    def execute_query(self, query, params=None):
        cur = self.conn.cursor()
        if params:
            cur.execute(f"SELECT {', '.join(map(str, params))} FROM {self.conn.database}", params)
        else:
            cur.execute(f"SELECT * FROM {self.conn.database}")

        rows = cur.fetchall()

        return rows

