import json
import flask
from flask import Flask, request

app = Flask(__name__)

class RestrictedUnpickler(json.JSONDecoder):
    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.obj = None

    def reset(self):
        self.obj = None

    def decode(self, s, *args, **kwargs):
        if not self.obj:
            self.obj = json.loads(s)
        return self.obj

@app.route('/upload', methods=['POST'])
def upload():
    data = request.get_data()
    deserialized_data = RestrictedUnpickler(json.loads(data)).decode()
    print(deserialized_data)
    return 'OK'

if __name__ == "__main__":
    app.run(debug=True)

